    """Restore the masked cells of the cyclic sequence/diagonal pattern."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # The first four rows have their distinctive diagonal values intact.
        # Rows 4-5 use the sequence beginning 2,3,4,...; later rows use
